pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        // Assume amount is strictly positive to enforce the intended invariant
        vm.assume(amount > 0);
        vm.assume(receiver != address(0));
        vm.assume(receiver != address(c));
        // Owner is the test contract itself (deployer).
        // Ensure the receiver has no initial balance beyond what we record.
        uint256 preBalance = receiver.balance;
        // The 'owner' check requires msg.sender == owner, which is the test contract.
        // Since constructor sets owner = msg.sender (test contract), we call directly.
        vm.deal(address(c), amount);
        c.sendTo(receiver, amount);
        uint256 postBalance = receiver.balance;
        assertEq(postBalance - preBalance, amount);
    }
}

