pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(receiver != address(0));
        amount = bound(amount, 0, 1 ether);
        bool referenceReverted;
        bool buggyReverted;

        // reference behavior
        C ref = new C();
        vm.prank(address(this));
        try ref.sendTo(receiver, amount) {
            referenceReverted = false;
        } catch {
            referenceReverted = true;
        }

        // mutant behavior
        C mut = new C();
        vm.prank(address(this));
        try mut.sendTo(receiver, amount) {
            buggyReverted = false;
        } catch {
            buggyReverted = true;
        }

        // Property: if amount is zero, the reference MUST revert, while the mutant does NOT revert.
        // This is equivalent to: whenever the reference and the mutant differ in revert behavior,
        // the reference must have reverted and the mutant must not have.
        if (referenceReverted != buggyReverted) {
            assertTrue(referenceReverted && !buggyReverted);
        }
    }
}

