pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        // Restrict amount to zero to isolate the changed condition
        amount = bound(amount, 0, 0);
        vm.assume(receiver != address(0));

        // Prank as owner to pass the owner check
        vm.prank(address(this));
        c.sendTo(receiver, amount);

        // The buggy contract allows sendTo with amount==0 to succeed,
        // while the reference always reverts on amount==0.
        // After a call that does not revert, the receiver's balance should be unchanged.
        // However, the bug is that it doesn't revert, so we check that the receiver's balance
        // is still zero, which holds for both, but the key difference is revert behavior.
        // To capture the difference, we note that the reference reverts, so
        // if we reach this point (no revert), the buggy contract succeeded.
        // The property: the call must ALWAYS revert for amount==0.
        // We assert true that we should never reach here; the fuzzer will find
        // that the buggy contract does not revert, thus the test fails by not reverting.
        // Actually, we need an assert that fails when the call succeeds.
        // So we assert that the call should have reverted, which is false for the buggy version.
        // We can use try/catch to detect revert.
        bool ok;
        try c.sendTo(receiver, amount) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "sendTo with zero amount should revert");
    }
}

