pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // seed the contract with Ether so it can transfer
        vm.deal(address(c), 100 ether);
    }
    function testFuzz_property(address receiver, uint256 amount) public {
        // Keep amount in admissible range: > 0 and <= contract's balance
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);
        vm.assume(amount <= 100 ether);

        uint256 balanceBefore = address(c).balance;
        vm.prank(address(this)); // owner is msg.sender of setUp (this contract)
        try c.sendTo(receiver, amount) {
            uint256 balanceAfter = address(c).balance;
            assertEq(balanceAfter, balanceBefore - amount);
        } catch {
            // If the call reverts, the rule is vacuously true for this input
            // (no state change expected). The assertion below handles this.
            // We need a boolean to encode the universal property:
            // the call MUST NOT silently succeed while breaking the balance invariant.
            revert("unexpected revert from reference");
            // Actually the reference should not revert for these valid inputs.
            // If it does, the property is still true (balance unchanged).
            // But to keep exactly one assertion and follow the pattern,
            // we assert true if revert, else assert the balance change.
        }
    }
}

